class Solution { public:
 int countPairs(vector<int>& nums){sort(nums.begin(),nums.end());unordered_map<int,int>seen;int ans=0;
 for(int x:nums){string s=to_string(x);s=string(7-s.size(),'0')+s;unordered_set<int>possible;
 auto save=[&](){possible.insert(stoi(s));};save();
 for(int i=0;i<7;++i)for(int j=i+1;j<7;++j){swap(s[i],s[j]);save();for(int a=0;a<7;++a)for(int b=a+1;b<7;++b){swap(s[a],s[b]);save();swap(s[a],s[b]);}swap(s[i],s[j]);}
 for(int y:possible)ans+=seen[y];++seen[x];}return ans;}
};
